import os
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/output/result.xlsx'
wb = load_workbook(path)  # keep formulas
ws_task = wb['Task']
ws_data = wb['Data']

print('=== Pre-work inspection: Task sheet A1:M55 ===')
for r in range(1, 56):
    row_out = []
    for c in range(1, 14):
        cell = ws_task.cell(row=r, column=c)
        v = cell.value
        # Mark formulas explicitly
        if isinstance(v, str) and v.startswith('='):
            row_out.append(f"{get_column_letter(c)}{r}:{v} [FORMULA]")
        else:
            row_out.append(f"{get_column_letter(c)}{r}:{v}")
    print(' | '.join(row_out))

print('\n=== Pay attention checks ===')
print('Task row 10 col H-L (years):')
for c in range(8, 13):
    addr = f"{get_column_letter(c)}10"
    print(addr, ws_task[addr].value)

print('\nTask series codes column D rows 12-31:')
task_codes = []
for r in range(12, 32):
    v = ws_task[f'D{r}'].value
    task_codes.append(v)
    print(f"D{r}: {v}")

target_yellow_ranges = [(12,17), (19,24), (26,31)]
print('\nTask yellow-cell ranges H12:L17, H19:L24, H26:L31 (current contents):')
for r0,r1 in target_yellow_ranges:
    for r in range(r0, r1+1):
        vals = []
        for c in range(8, 13):
            addr = f"{get_column_letter(c)}{r}"
            v = ws_task[addr].value
            if isinstance(v,str) and v.startswith('='):
                vals.append(f"{addr}={v}")
            else:
                vals.append(f"{addr}:{v}")
        print(' '.join(vals))

print('\nRows 35-40 labels (A-G):')
for r in range(35, 41):
    parts=[]
    for c in range(1, 8):
        v = ws_task.cell(row=r, column=c).value
        parts.append(v)
    print(r, parts)

print('\nRows 42-47 labels (A-G):')
for r in range(42, 48):
    parts=[]
    for c in range(1, 8):
        v = ws_task.cell(row=r, column=c).value
        parts.append(v)
    print(r, parts)

print('\nRow 50 labels (A-G):')
parts=[]
for c in range(1, 8):
    parts.append(ws_task.cell(row=50, column=c).value)
print(50, parts)

print('\n=== Pre-work inspection: Data sheet rows 1-40 (A:??) ===')
# Print A-Z for rows 1-40 for visibility
for r in range(1, 41):
    row_out=[]
    for c in range(1, 27):
        v = ws_data.cell(row=r, column=c).value
        row_out.append(f"{get_column_letter(c)}{r}:{v}")
    print(' | '.join(row_out))

# Helper: yearlike

def is_yearlike(x):
    if isinstance(x, int):
        return 1900 <= x <= 2100
    if isinstance(x, float) and x.is_integer():
        xi = int(x)
        return 1900 <= xi <= 2100
    if isinstance(x, str):
        s=x.strip()
        if s.isdigit() and len(s)==4:
            xi=int(s)
            return 1900<=xi<=2100
    return False

print('\n=== Infer Data layout (focus rows 21-38) ===')
rows = list(range(21, 39))
# Find series-code column by matching task codes
codes_set = set([c for c in task_codes if c is not None])
series_col_candidates = list(range(1, 21))
col_match_counts=[]
for c in series_col_candidates:
    vals=[ws_data.cell(row=r, column=c).value for r in rows]
    count=sum(1 for v in vals if v in codes_set)
    if count:
        col_match_counts.append((count,c))
series_col = max(col_match_counts)[1] if col_match_counts else 1
print('Detected series-code column (best match count):', get_column_letter(series_col), max(col_match_counts)[0] if col_match_counts else 0)

# Find year header row by counting yearlikes in each row
best = None
for r in range(1, 41):
    years=[]
    for c in range(1, 80):
        v = ws_data.cell(row=r, column=c).value
        if is_yearlike(v):
            years.append((c,v))
    if years:
        score = len(years)
        # prefer rows <= 25
        pref = 0 if r <= 25 else 1
        key = (score, -pref, -r)  # score then prefer small r? Actually closer to 25, so higher r within <=25
        if best is None or key > best[0]:
            best = (key, r, years)

year_header_row = best[1] if best else 20
# Determine year columns and contiguous range
year_cols = [c for c,_ in best[2]] if best else []
# Use min/max of year cols
if year_cols:
    min_year_col = min(year_cols)
    max_year_col = max(year_cols)
else:
    min_year_col, max_year_col = 2, 10
print('Detected year header row:', year_header_row)
print('Year columns span:', get_column_letter(min_year_col), '-', get_column_letter(max_year_col))

# Print exact year headers in that row
print('Year headers:')
for c in range(min_year_col, max_year_col+1):
    v = ws_data.cell(row=year_header_row, column=c).value
    if is_yearlike(v):
        print(f"{get_column_letter(c)}{year_header_row}: {v}")

print('\nExact series codes in Data rows 21-38 for detected series column:')
for r in rows:
    print(f"{get_column_letter(series_col)}{r}: {ws_data.cell(row=r, column=series_col).value}")

# Narrow value columns to those that intersect year cols and have numeric data
value_cols = []
for c in range(min_year_col, max_year_col+1):
    nums = 0
    for r in rows:
        v = ws_data.cell(row=r, column=c).value
        if isinstance(v, (int, float)):
            nums += 1
    if nums:
        value_cols.append(c)
if value_cols:
    col_start = min(value_cols)
    col_end = max(value_cols)
else:
    col_start, col_end = min_year_col, max_year_col

print('Numeric value columns span:', get_column_letter(col_start), '-', get_column_letter(col_end))

# ---- Step 1: Populate lookup formulas ----
values_range = f"Data!${get_column_letter(col_start)}$21:${get_column_letter(col_end)}$38"
series_range = f"Data!${get_column_letter(series_col)}$21:${get_column_letter(series_col)}$38"
year_range = f"Data!${get_column_letter(col_start)}${year_header_row}:${get_column_letter(col_end)}${year_header_row}"

print('\n=== Writing INDEX/MATCH formulas ===')
print('Using ranges:')
print(' values_range:', values_range)
print(' series_range:', series_range)
print(' year_range  :', year_range)

for r0, r1 in target_yellow_ranges:
    for r in range(r0, r1+1):
        for c in range(8, 13):  # H-L
            col_letter = get_column_letter(c)
            formula = (
                f"=INDEX({values_range},"
                f" MATCH($D{r}, {series_range}, 0),"
                f" MATCH({col_letter}$10, {year_range}, 0))"
            )
            ws_task.cell(row=r, column=c).value = formula

# ---- Step 2: Net capacity headroom and summary stats ----
# Determine which block corresponds to available/occupied/staffed by looking at nearby labels

def block_context(start_row):
    texts=[]
    for rr in (start_row-1, start_row):
        for cc in range(1, 8):
            v = ws_task.cell(row=rr, column=cc).value
            if isinstance(v, str) and v.strip():
                texts.append(v.strip().lower())
    return ' '.join(texts)

block_starts = [12, 19, 26]
contexts = {s: block_context(s) for s in block_starts}

available_start = occupied_start = staffed_start = None
for s, txt in contexts.items():
    if 'available' in txt and available_start is None:
        available_start = s
    if 'occupied' in txt and occupied_start is None:
        occupied_start = s
    if ('staffed' in txt) or ('bed capacity' in txt) or ('capacity' in txt):
        # if multiple contain capacity, we'll handle after
        if staffed_start is None:
            staffed_start = s

# Fallback assumptions if not detected
if available_start is None:
    available_start = 12
if occupied_start is None:
    occupied_start = 19
if staffed_start is None or staffed_start in (available_start, occupied_start):
    # default third block as staffed
    staffed_start = 26

print('\n=== Block mapping for headroom ===')
print('Contexts:', contexts)
print('available_start:', available_start, 'occupied_start:', occupied_start, 'staffed_start:', staffed_start)

# Write headroom formulas H35:L40
