        return 'MIN'
    if 'max' in t:
        return 'MAX'
    if 'median' in t:
        return 'MEDIAN'
    if 'mean' in t or 'average' in t:
        return 'AVERAGE'
    if '25' in t or '1st' in t or 'first quartile' in t or 'q1' in t:
        return 'P25'
    if '75' in t or '3rd' in t or 'third quartile' in t or 'q3' in t:
        return 'P75'
    return None

