}
for r in range(42, 48):
    stat = row_to_stat.get(r) or fallback[r]
    for c in range(8, 13):
        col = get_column_letter(c)
        rng = f"{col}35:{col}40"
        if stat == 'MIN':
            fml = f"=MIN({rng})"
