            fml = f"=MAX({rng})"
        elif stat == 'MEDIAN':
            fml = f"=MEDIAN({rng})"
        elif stat == 'AVERAGE':
            fml = f"=AVERAGE({rng})"
        elif stat == 'P25':
            fml = f"=PERCENTILE.INC({rng},0.25)"
