    head_rng = f"{col}35:{col}40"
    cap_rng = f"{col}{staffed_start}:{col}{staffed_start+5}"
    ws_task.cell(row=50, column=c).value = f"=SUMPRODUCT({head_rng},{cap_rng})/SUM({cap_rng})"

# Save
wb.save(path)
print('\nSaved workbook to', path)

# Verify by reopening and printing sample formulas
wb2 = load_workbook(path)
